events.detection_query:
SecurityEvent
| where EventID == 4634
| join kind=leftanti (
    SecurityEvent | where EventID == 4624 | project TargetLogonId
) on TargetLogonId
// rows here are logoffs with no matching logon in the retained window

SecurityEvent
| where EventID == 4649
// any occurrence at all is rare enough to warrant review; volume itself is the alert

SecurityEvent
| where EventID == 1102
// any occurrence is high-priority; rarity itself is the alert

SecurityEvent
| where EventID == 4713
// rare by design; alert on any occurrence outside a documented Kerberos policy change window

SecurityEvent
| where EventID == 4728 and TargetGroupName == "Domain Admins"
// membership into a tier-0 group should be rare enough that any hit warrants review
